parameters.jsCode:
const items = $input.all();

const texto = items
  .map(item => {
    const data = item.json ?? {};
    // Busca clave/valor dentro de fields o directamente en json
    const fuente = data.fields ?? data;
    const clave = fuente.clave;
    const valor = fuente.valor;

    // Descarta items sin clave
    if (clave === undefined) return null;

    return `- id: ${data.id ?? "?"} | ${clave}: ${valor}`;
  })
  .filter(Boolean)   // saca los null (items descartados)
  .join("\n");

return [{ json: { memoria: texto } }];

// Devuelve un item por cada elemento del array "guardar"
const salida = [];

for (const item of $input.all()) {
  const guardar = item.json.guardar;
  if (Array.isArray(guardar)) {
    for (const registro of guardar) {
      salida.push({ json: registro });
    }
  }
}

return salida;

